window.JIN_289_RESTORATIONS = {"reviewed_at":"2026-10-07","scope":"western_jin","policy":"舊289、308圖只作查找研究的線索，後續Codex修訂與使用者裁定優先；爵表與《晉書》、顧江龍、姚樂胡阿祥等研究互證。本輪289為正式多郡政策的展示分界，不稱晉武帝卒於289。當年列變更後結果；問號、未知國主及單純死亡不能自動撤國。已採支郡除明確去除或有撤銷、改封等相反證據外延續，未逐年記載處標作展示推定；不因國主更替、舊資料終年或退出文字實際控制範圍而撤銷。","title_periods":[{"ids":["p073"],"begin":289,"end":289,"name":"秦國","rank":"王","note":"289扶風王改順陽，原扶風本國改秦；《晉書》地理志另繫惠帝即位290，本輪沿封爵表289展示。始平為有研究依據的支郡，不改以京兆為本國。"},{"ids":["p163"],"begin":289,"end":290,"name":"楚國","rank":"王","note":"舊289年封國圖、顧江龍研究及《晉書》宗室傳所繫楚王司馬瑋，以襄陽為本國。楚為多郡王國而旁郡未詳，只呈已知本國，不虛造支郡；291被誅國除。"},{"ids":["p101"],"begin":289,"end":306,"name":"漢國","rank":"王","note":"漢王以漢中為本國。迪300遇害未見獨立國除明文，固301續封，本輪不因國主死亡造一年郡的空檔；307沿已批准Word的永嘉改濟南展示推定，還漢中郡。"},{"ids":["p053"],"begin":289,"end":303,"name":"代國","rank":"王","note":"289封司馬演為代王；嗣子廓304已改中都，故代王國列289—303。後來拓跋代公、代王另按現有資料保留，不與此次司馬氏代國混同。"},{"ids":["p175"],"begin":289,"end":290,"name":"長沙國","rank":"王","note":"289年司馬乂初封長沙；南平、衡陽支郡沿舊圖及顧江龍、姚樂胡阿祥研究方案回推，標為展示推定。291改常山，原長沙郡恢復；301復封另依既有條目。"},{"ids":["p046"],"begin":275,"end":290,"name":"常山郡","rank":null,"note":"司馬殷275年薨、無後，275—290未見可承接的郡級王、公、侯；291司馬乂改封常山才復國。本輪按使用者明確指定修正，301以後原有改郡裁定保留。"},{"ids":["p033"],"begin":291,"end":313,"name":"中丘國","rank":"王","note":"中丘郡級擬定範圍隨太原王約291改封中丘而起；291是本輪展示推定，不斷言確年。中丘縣此前仍歸趙。末王鑠311終年僅舊表疑推，國絕確年未有獨立依據，不據問號提前撤國；本年國主不明時不補姓名年次。"},{"ids":["p165"],"begin":266,"end":300,"name":"義陽國","rank":"王","note":"舊289封國圖及宗室王表可證義陽王系，本國採現有義陽郡範圍；301司馬威因害惠帝被誅、國除，自本年還郡。"},{"ids":["p146"],"begin":283,"end":306,"name":"東萊國","rank":"王","note":"283封司馬蕤為東萊王。301雖遭廢，後追復其封、子遵繼嗣，不能當永久廢國。遵永嘉中改華容，確年未詳，本輪沿舊307問號起點取307作改封展示，283—306延續國，後段為推定。"},{"ids":["p191"],"begin":289,"end":290,"name":"毗陵國","rank":"王","note":"289以毗陵封司馬儀，291無子國除；恢復舊289圖可用結論，291當年即還毗陵郡。"},{"ids":["p163"],"begin":300,"end":310,"name":"襄陽國","rank":"王","note":"300司馬尚封襄陽，301立皇太孫，同年司馬范接封；按當年結果不留一年郡的空檔。311范被害國除，回襄陽郡。與289—290楚國分期，不混用國名。"},{"ids":["p184"],"begin":307,"end":310,"name":"竟陵國","rank":"王","note":"司馬楙307徙竟陵，舊308圖有據；311被害、國除，當年還竟陵郡。"},{"ids":["p164"],"begin":289,"end":305,"name":"南陽郡","rank":null,"note":"289司馬柬由南陽改秦，南陽不再沿舊王名著色；306司馬模另受南陽封，故只在289—305還郡，保留306以後新封。"},{"ids":["p014"],"begin":289,"end":300,"name":"濮陽郡","rank":null,"note":"289司馬允由濮陽改淮南，當年舊國還郡；301司馬臧短暫改封又卒，沿上一輪301起廢國裁定，不重造年末濮陽國。"},{"ids":["p192"],"begin":311,"end":316,"name":"吳郡","rank":null,"note":"311年吳國明載國絕，依當年變更後結果解除本國及丹楊、吳興支屬，恢復郡名；不將311仍列在司馬晏的多郡關係期段內。"},{"ids":["p189"],"begin":311,"end":316,"name":"丹楊郡","rank":null,"note":"311年吳國明載國絕，依當年變更後結果解除本國及丹楊、吳興支屬，恢復郡名；不將311仍列在司馬晏的多郡關係期段內。"},{"ids":["p193"],"begin":311,"end":316,"name":"吳興郡","rank":null,"note":"311年吳國明載國絕，依當年變更後結果解除本國及丹楊、吳興支屬，恢復郡名；不將311仍列在司馬晏的多郡關係期段內。"}],"proto_members":[{"id":"p048","begin":277,"end":288},{"id":"p143","begin":283,"end":288},{"id":"p154","begin":277,"end":288}],"chen":{"primary_id":"p025","branch_id":"p026","formal_begin":289,"text_end":313,"map_end":316,"county_ids":["c0231","c0232","c0233","c0234"],"note":"289以前按梁國行內（陳支郡）縣組展示，不另計郡；289起依使用者正式多郡分界，復用陳支郡行並計一郡，陳、項、陽夏、武平四縣只列陳支郡。這是本輪制度展示裁定，不聲稱史料已證289正好復置陳郡機構。"},"zhongqiu":{"id":"p033","parent_id":"p032","county_id":"c0283","display_begin":291,"note":"中丘此前是趙屬縣；約291年改封後才啟用擬定郡級國面，不把283後的模糊始年硬排為283即置。"},"source_links":[{"title":"晉朝藩王列表","url":"https://zh.wikipedia.org/zh-cn/晉朝藩王列表#代國→中都國"},{"title":"《晉書》卷14·地理志","url":"https://zh.wikisource.org/zh-hant/晉書/卷014"},{"title":"《晉書》卷37·宗室","url":"https://zh.wikisource.org/zh-hant/晉書/卷037"},{"title":"《晉書》卷38·宗室","url":"https://zh.wikisource.org/zh-hant/晉書/卷038"},{"title":"《晉書》卷59","url":"https://zh.wikisource.org/zh-hant/晉書/卷059"},{"title":"《晉書》卷64·武十三王","url":"https://zh.wikisource.org/zh-hant/晉書/卷064"}]};
